export interface ConnectorConfig {
  /** Slack channel ID or name (e.g., C01234567 or #general) */
  slackChannel: string
  /** Slack Bot User OAuth Token with chat:write scope */
  slackBotToken: string
  /** Optional injected fetch for testing */
  fetch?: typeof fetch
}

export interface CalendlyWebhookPayload {
  event: string
  payload: {
    resource: {
      uri: string
      status: string
      start_time: string
      created_at: string
      cancelled_at: string | null
      name: string
      email: string
      answers: Array<{
        question: string
        answer: string
      }>
    }
  }
}

export interface SlackPostMessageResponse {
  ok: boolean
  channel: string
  ts: string
}

export interface ConnectorResult {
  slackChannel: string
  slackTimestamp: string
}

function validatePayload(payload: unknown): asserts payload is CalendlyWebhookPayload {
  if (!payload || typeof payload !== 'object') {
    throw new Error('Payload must be an object')
  }
  const p = payload as Record<string, unknown>
  if (p.event !== 'invitee.created') {
    throw new Error(`Expected event "invitee.created", got "${p.event}"`)
  }
  if (!p.payload || typeof p.payload !== 'object') {
    throw new Error('Missing payload.resource')
  }
  const resource = (p.payload as Record<string, unknown>).resource
  if (!resource || typeof resource !== 'object') {
    throw new Error('Missing payload.resource')
  }
  const r = resource as Record<string, unknown>
  if (typeof r.name !== 'string' || !r.name.trim()) {
    throw new Error('Missing or empty invitee name')
  }
  if (typeof r.email !== 'string' || !r.email.trim()) {
    throw new Error('Missing or empty invitee email')
  }
  if (!Array.isArray(r.answers)) {
    throw new Error('Missing or invalid answers array')
  }
  for (const ans of r.answers) {
    if (!ans || typeof ans !== 'object' || typeof (ans as Record<string, unknown>).question !== 'string' || typeof (ans as Record<string, unknown>).answer !== 'string') {
      throw new Error('Each answer must have question and answer strings')
    }
  }
}

function validateConfig(config: ConnectorConfig): void {
  if (!config.slackChannel || typeof config.slackChannel !== 'string') {
    throw new Error('Config must include slackChannel (string)')
  }
  if (!config.slackBotToken || typeof config.slackBotToken !== 'string') {
    throw new Error('Config must include slackBotToken (string)')
  }
}

function formatSlackMessage(resource: CalendlyWebhookPayload['payload']['resource']): string {
  const lines: string[] = ['New meeting booked!', `Name: ${resource.name}`, `Email: ${resource.email}`, 'Answers:']
  for (const ans of resource.answers) {
    lines.push(`- ${ans.question}: ${ans.answer}`)
  }
  return lines.join('\n')
}

export async function handle(payload: unknown, config: ConnectorConfig): Promise<ConnectorResult> {
  validatePayload(payload)
  validateConfig(config)

  const typedPayload = payload as CalendlyWebhookPayload
  const text = formatSlackMessage(typedPayload.payload.resource)

  const fetchImpl = config.fetch ?? fetch
  const url = 'https://slack.com/api/chat.postMessage'
  const body = JSON.stringify({ channel: config.slackChannel, text })

  const response = await fetchImpl(url, {
    method: 'POST',
    headers: {
      'Authorization': `Bearer ${config.slackBotToken}`,
      'Content-Type': 'application/json'
    },
    body
  })

  if (!response.ok) {
    throw new Error(`Slack API error: ${response.status} ${response.statusText} at POST ${url}`)
  }

  const data = await response.json() as SlackPostMessageResponse
  if (!data.ok) {
    throw new Error(`Slack API returned ok=false: ${JSON.stringify(data)}`)
  }

  return {
    slackChannel: data.channel,
    slackTimestamp: data.ts
  }
}

