      })
      return jsonResponse({ ok: true, channel: 'C01234567', ts: '1743859200.000200' })
    })

    const config: ConnectorConfig = {
      slackChannel: 'C01234567',
      slackBotToken: 'xoxb-test-token',
      fetch
    }

    const result = await handle(SOURCE_EXAMPLE as unknown as CalendlyWebhookPayload, config)
