      ...SOURCE_EXAMPLE,
      payload: { ...SOURCE_EXAMPLE.payload, resource: { ...SOURCE_EXAMPLE.payload.resource, answers: undefined } }
    }
    await expect(handle(badPayload as unknown as CalendlyWebhookPayload, config)).rejects.toThrow('answers')
